uestions, <?= (int)$subject['study_resource_count'] ?> resources</li><?php endforeach; ?></ul><p>Shallow topics: <?php $shallowBoardTopics = array_values(array_filter($depth['shallow_topics'] ?? [], static fn(array $item): bool => ($item['board_id'] ?? '') === (string)$boardId)); ?><?= $escape(implode(', ', array_column($shallowBoardTopics, 'target')) ?: 'none') ?></p><p>Priority candidates: <?php $boardPriorities = array_values(array_filter($priorityRows, static fn(array $item): bool => ($item['board_id'] ?? '') === (string)$boardId)); ?><?= $escape(implode(', ', array_column($boardPriorities, 'target')) ?: 'none') ?></p><?php if (!empty($integrityBoard['defects'])): ?><ul><?php foreach ($integrityBoard['defects'] as $defect=>$ids): ?><?php if ($ids !== []): ?><li><?= $escape($defect) ?>: <?= $escape(implode(', ', array_map('strval', (array)$ids))) ?></li><?php endif; ?><?php endforeach; ?></ul><?php endif; ?></details></td></tr><?php endforeach; ?></tbody></table></div></section>

